#pragma once
#include "Wire.h"
template<>struct Wire<VN_STATE>;
template<>struct Wire<VN_FRAME>;
template<>struct Wire<TITAN_AUTHORIZATION_CHALLENGE>;
template<>struct Wire<TITAN_AUTHORIZATION_TOKEN>;
template<>struct Wire<VN_STATE> {static Json Encode(const VN_STATE& v){Json j=Json::object();j["version"]=EncodeWire(v.version);j["size"]=EncodeWire(v.size);j["running"]=EncodeWire(v.running);j["connected"]=EncodeWire(v.connected);j["queued"]=EncodeWire(v.queued);j["capacity"]=EncodeWire(v.capacity);j["max_frame"]=EncodeWire(v.max_frame);j["reserved"]=EncodeWire(v.reserved);j["mac"]=EncodeWire(v.mac);j["padding"]=EncodeWire(v.padding);j["transmitted"]=EncodeWire(v.transmitted);j["received"]=EncodeWire(v.received);j["dropped"]=EncodeWire(v.dropped);return j;}static void Decode(const Json& j,VN_STATE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="size")DecodeWire(it.value(),v.size);else if(it.key()=="running")DecodeWire(it.value(),v.running);else if(it.key()=="connected")DecodeWire(it.value(),v.connected);else if(it.key()=="queued")DecodeWire(it.value(),v.queued);else if(it.key()=="capacity")DecodeWire(it.value(),v.capacity);else if(it.key()=="max_frame")DecodeWire(it.value(),v.max_frame);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else if(it.key()=="mac")DecodeWire(it.value(),v.mac);else if(it.key()=="padding")DecodeWire(it.value(),v.padding);else if(it.key()=="transmitted")DecodeWire(it.value(),v.transmitted);else if(it.key()=="received")DecodeWire(it.value(),v.received);else if(it.key()=="dropped")DecodeWire(it.value(),v.dropped);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<VN_FRAME> {static Json Encode(const VN_FRAME& v){Json j=Json::object();j["length"]=EncodeWire(v.length);j["data"]=EncodeWire(v.data);return j;}static void Decode(const Json& j,VN_FRAME& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="length")DecodeWire(it.value(),v.length);else if(it.key()=="data")DecodeWire(it.value(),v.data);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<TITAN_AUTHORIZATION_CHALLENGE> {static Json Encode(const TITAN_AUTHORIZATION_CHALLENGE& v){Json j=Json::object();j["magic"]=EncodeWire(v.magic);j["version"]=EncodeWire(v.version);j["product"]=EncodeWire(v.product);j["duration_seconds"]=EncodeWire(v.duration_seconds);j["nonce"]=EncodeWire(v.nonce);return j;}static void Decode(const Json& j,TITAN_AUTHORIZATION_CHALLENGE& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="magic")DecodeWire(it.value(),v.magic);else if(it.key()=="version")DecodeWire(it.value(),v.version);else if(it.key()=="product")DecodeWire(it.value(),v.product);else if(it.key()=="duration_seconds")DecodeWire(it.value(),v.duration_seconds);else if(it.key()=="nonce")DecodeWire(it.value(),v.nonce);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
template<>struct Wire<TITAN_AUTHORIZATION_TOKEN> {static Json Encode(const TITAN_AUTHORIZATION_TOKEN& v){Json j=Json::object();j["permission"]=EncodeWire(v.permission);j["signature"]=EncodeWire(v.signature);return j;}static void Decode(const Json& j,TITAN_AUTHORIZATION_TOKEN& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="permission")DecodeWire(it.value(),v.permission);else if(it.key()=="signature")DecodeWire(it.value(),v.signature);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
